<?php
namespace App\Http\Controllers;
use App\Models\Product;
use App\Services\CartService;
use Illuminate\Http\Request;
class CartController extends Controller {public function __construct(private CartService $cart){}public function index(){return view('store.cart',['items'=>$this->cart->items(),'totals'=>$this->cart->totals()]);}public function store(Request $r,Product $product){$data=$r->validate(['quantity'=>'required|integer|min:1|max:10','variant_id'=>'nullable|integer','color'=>'nullable|string|max:60','size'=>'nullable|string|max:30']);$this->cart->add($product,$data['quantity'],$data['variant_id']??null,$data['color']??null,$data['size']??null);return back()->with('success','Added to your bag.');}public function update(Request $r,string $key){$data=$r->validate(['quantity'=>'required|integer|min:0|max:10']);$this->cart->update($key,$data['quantity']);return back()->with('success','Bag updated.');}public function destroy(string $key){$this->cart->remove($key);return back()->with('success','Item removed.');}public function coupon(Request $r){$this->cart->applyCoupon($r->validate(['code'=>'required|string|max:30'])['code']);return back()->with('success','Coupon applied.');}public function removeCoupon(){session()->forget('sarai_coupon');return back()->with('success','Coupon removed.');}}
